<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import * as systemApi from '@/api/system'

const tab = ref('roles')
const loading = ref(false)
const roles = ref([])
const depts = ref([])
const dicts = ref([])
const logs = ref([])
const menus = ref([])
const selectedRole = ref(null)
const selectedMenuIds = ref([])
const menuDialogVisible = ref(false)
const dictType = ref('status')
const dialogVisible = ref(false)
const dialogKind = ref('role')
const editingId = ref(null)
const roleForm = reactive({ roleCode: '', roleName: '', dataScope: 1, status: 1 })
const deptForm = reactive({ parentId: null, deptName: '', sortNo: 1 })
const dictForm = reactive({ dictType: 'status', dictLabel: '', dictValue: '', sortNo: 1 })

const dialogTitles = { role: '角色', dept: '部门', dict: '字典项' }
function reset(form, values) { Object.assign(form, values) }
async function load() {
  loading.value = true
  try {
    if (tab.value === 'roles') { const [roleResponse, menuResponse] = await Promise.all([systemApi.getRoles(), systemApi.getMenus()]); roles.value = roleResponse.data || []; menus.value = menuResponse.data || [] }
    if (tab.value === 'depts') depts.value = (await systemApi.getDepts()).data || []
    if (tab.value === 'dicts') dicts.value = (await systemApi.getDicts(dictType.value.trim() || 'status')).data || []
    if (tab.value === 'logs') logs.value = (await systemApi.getOperLogs({ pageNum: 1, pageSize: 50 })).data?.list || []
  } catch (error) { ElMessage.error(error.message || '系统配置加载失败') } finally { loading.value = false }
}
function openCreate(kind) { dialogKind.value = kind; editingId.value = null; if (kind === 'role') reset(roleForm, { roleCode: '', roleName: '', dataScope: 1, status: 1 }); if (kind === 'dept') reset(deptForm, { parentId: null, deptName: '', sortNo: 1 }); if (kind === 'dict') reset(dictForm, { dictType: dictType.value || 'status', dictLabel: '', dictValue: '', sortNo: 1 }); dialogVisible.value = true }
function openEdit(kind, item) { dialogKind.value = kind; editingId.value = item.id; if (kind === 'role') reset(roleForm, { roleCode: item.roleCode, roleName: item.roleName, dataScope: item.dataScope || 1, status: item.status ?? 1 }); if (kind === 'dept') reset(deptForm, { parentId: item.parentId || null, deptName: item.deptName, sortNo: item.sortNo || 0 }); if (kind === 'dict') reset(dictForm, { dictType: item.dictType, dictLabel: item.dictLabel, dictValue: item.dictValue, sortNo: item.sortNo || 0 }); dialogVisible.value = true }
function selectRole(role) { selectedRole.value = role; selectedMenuIds.value = [...(role.menuIds || [])]; menuDialogVisible.value = true }
async function saveRoleMenus() { const roleId = selectedRole.value?.id; if (!roleId) return; try { await systemApi.updateRoleMenus(roleId, selectedMenuIds.value.map(Number)); ElMessage.success('角色菜单权限已保存'); menuDialogVisible.value = false; await load(); selectedRole.value = roles.value.find((role) => role.id === roleId) || null } catch (error) { ElMessage.error(error.message || '角色菜单保存失败') } }
async function submitDialog() {
  try {
    if (dialogKind.value === 'role') { const payload = { ...roleForm, dataScope: Number(roleForm.dataScope) }; editingId.value ? await systemApi.updateRole(editingId.value, payload) : await systemApi.createRole(payload) }
    if (dialogKind.value === 'dept') { const payload = { ...deptForm, parentId: deptForm.parentId ? Number(deptForm.parentId) : null, sortNo: Number(deptForm.sortNo) }; editingId.value ? await systemApi.updateDept(editingId.value, payload) : await systemApi.createDept(payload) }
    if (dialogKind.value === 'dict') { const payload = { ...dictForm, sortNo: Number(dictForm.sortNo) }; editingId.value ? await systemApi.updateDict(editingId.value, payload) : await systemApi.createDict(payload) }
    ElMessage.success(`${dialogTitles[dialogKind.value]}${editingId.value ? '已更新' : '已创建'}`); dialogVisible.value = false; await load()
  } catch (error) { ElMessage.error(error.message || `${dialogTitles[dialogKind.value]}保存失败`) }
}
async function removeRole(role) { try { await ElMessageBox.confirm(`确认删除角色“${role.roleName}”吗？`, '删除角色', { type: 'warning' }); await systemApi.deleteRole(role.id); ElMessage.success('角色已删除'); if (selectedRole.value?.id === role.id) selectedRole.value = null; await load() } catch (error) { if (error !== 'cancel') ElMessage.error(error.message || '角色删除失败') } }
async function removeDept(dept) { try { await ElMessageBox.confirm(`确认删除部门“${dept.deptName}”吗？删除前需先移出下级部门和用户。`, '删除部门', { type: 'warning' }); await systemApi.deleteDept(dept.id); ElMessage.success('部门已删除'); await load() } catch (error) { if (error !== 'cancel') ElMessage.error(error.message || '部门删除失败') } }
async function removeDict(item) { try { await ElMessageBox.confirm(`确认删除字典项“${item.dictLabel}”吗？`, '删除字典项', { type: 'warning' }); await systemApi.deleteDict(item.id); ElMessage.success('字典项已删除'); await load() } catch (error) { if (error !== 'cancel') ElMessage.error(error.message || '字典项删除失败') } }
onMounted(load)
</script>

<template>
  <div class="page-intro"><div><h2>系统配置</h2><p>集中维护角色、部门、字典和操作日志，支撑权限与业务配置。</p></div><button class="table-action" type="button" @click="load">刷新</button></div>
  <div class="tab-bar"><button v-for="item in [['roles','角色'],['depts','部门'],['dicts','字典'],['logs','操作日志']]" :key="item[0]" class="table-action" :class="{ active: tab === item[0] }" type="button" @click="tab = item[0]; load()">{{ item[1] }}</button></div>
  <section v-if="tab === 'roles'" class="soft-card table-card"><div class="section-toolbar"><div><strong>角色列表</strong><span>按最小权限分配数据范围和菜单</span></div><button class="primary-button compact-button" type="button" @click="openCreate('role')">新增角色</button></div><div v-if="loading" class="empty-state">加载中…</div><table v-else class="data-table"><thead><tr><th>编码</th><th>名称</th><th>数据范围</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="role in roles" :key="role.id"><td>{{ role.roleCode }}</td><td>{{ role.roleName }}</td><td>{{ role.dataScope }}</td><td>{{ role.status === 1 ? '启用' : '停用' }}</td><td class="row-actions"><button class="table-action" type="button" @click="selectRole(role)">配置菜单</button><button class="table-action" type="button" @click="openEdit('role', role)">编辑</button><button class="table-action danger-action" type="button" @click="removeRole(role)">删除</button></td></tr></tbody></table></section>
  <section v-else-if="tab === 'depts'" class="soft-card table-card"><div class="section-toolbar"><div><strong>部门列表</strong><span>删除前需先移出下级部门和用户</span></div><button class="primary-button compact-button" type="button" @click="openCreate('dept')">新增部门</button></div><table class="data-table"><thead><tr><th>ID</th><th>部门名称</th><th>父部门</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="dept in depts" :key="dept.id"><td>{{ dept.id }}</td><td>{{ dept.deptName }}</td><td>{{ dept.parentId || '—' }}</td><td>{{ dept.status === 1 ? '启用' : '停用' }}</td><td class="row-actions"><button class="table-action" type="button" @click="openEdit('dept', dept)">编辑</button><button class="table-action danger-action" type="button" @click="removeDept(dept)">删除</button></td></tr></tbody></table></section>
  <section v-else-if="tab === 'dicts'" class="soft-card table-card"><div class="section-toolbar"><div><strong>字典项</strong><span>先按类型筛选，再维护显示标签和值</span></div><button class="primary-button compact-button" type="button" @click="openCreate('dict')">新增字典项</button></div><p class="dict-help">字典是系统统一选项表，例如“设备状态”“巡检结果”“工单状态”。页面读取字典后，所有表单使用同一套标签和值，避免不同页面写出不一致的状态文字。</p><div class="toolbar"><input v-model="dictType" class="form-input" placeholder="查询字典类型，例如 status" @keyup.enter="load" /><button class="table-action" type="button" @click="load">查询</button></div><table class="data-table"><thead><tr><th>类型</th><th>标签</th><th>值</th><th>排序</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in dicts" :key="item.id"><td>{{ item.dictType }}</td><td>{{ item.dictLabel }}</td><td>{{ item.dictValue }}</td><td>{{ item.sortNo }}</td><td>{{ item.status === 1 ? '启用' : '停用' }}</td><td class="row-actions"><button class="table-action" type="button" @click="openEdit('dict', item)">编辑</button><button class="table-action danger-action" type="button" @click="removeDict(item)">删除</button></td></tr></tbody></table></section>
  <section v-else class="soft-card table-card"><table class="data-table"><thead><tr><th>时间</th><th>用户</th><th>操作</th><th>请求</th><th>结果</th><th>Trace ID</th></tr></thead><tbody><tr v-for="log in logs" :key="log.id"><td>{{ log.createdTime }}</td><td>{{ log.username || log.userId || '—' }}</td><td>{{ log.operation }}</td><td>{{ log.requestMethod }} {{ log.requestUri }}</td><td>{{ log.success === 1 ? '成功' : '失败' }}</td><td>{{ log.traceId || '—' }}</td></tr></tbody></table></section>
  <el-dialog v-if="selectedRole" v-model="menuDialogVisible" :title="`${selectedRole.roleName} · 菜单权限`" width="760px" destroy-on-close><p class="dialog-tip">只勾选该角色真正需要看到或执行的功能。菜单权限控制页面入口，操作权限控制新增、领取、派工等具体动作。</p><div class="permission-dialog"><label v-for="menu in menus" :key="menu.id" class="menu-option"><input v-model="selectedMenuIds" type="checkbox" :value="menu.id" /> <span>{{ menu.menuName }}</span><small>{{ menu.permissionCode || menu.routePath || '按钮权限' }}</small></label></div><div class="dialog-actions"><button class="secondary-button" type="button" @click="menuDialogVisible = false">取消</button><button class="primary-button compact-button" type="button" @click="saveRoleMenus">保存权限</button></div></el-dialog>
  <el-dialog v-model="dialogVisible" :title="`${editingId ? '编辑' : '新增'}${dialogTitles[dialogKind]}`" width="500px" destroy-on-close><p class="dialog-tip">{{ dialogKind === 'role' ? '角色编码用于权限识别，角色名称用于页面展示；保存后还可以继续配置菜单和操作权限。' : dialogKind === 'dept' ? '部门关系用于用户归属和数据范围，请先确认上级部门。' : '字典值供业务表单读取，建议保持同一类型下值唯一。' }}</p><form class="dialog-form" @submit.prevent="submitDialog"><template v-if="dialogKind === 'role'"><label class="form-label">角色编码</label><input v-model="roleForm.roleCode" class="form-input" required placeholder="例如：maintenance_lead（英文小写和下划线）" /><label class="form-label">角色名称</label><input v-model="roleForm.roleName" class="form-input" required placeholder="例如：维修主管" /><label class="form-label">数据范围</label><select v-model.number="roleForm.dataScope" class="form-input"><option :value="1">全部数据</option><option :value="2">本部门数据</option><option :value="3">本人数据</option></select><label class="form-label">角色状态</label><select v-model.number="roleForm.status" class="form-input"><option :value="1">启用</option><option :value="0">停用</option></select></template><template v-else-if="dialogKind === 'dept'"><label class="form-label">部门名称</label><input v-model="deptForm.deptName" class="form-input" required placeholder="例如：一号车间" /><label class="form-label">上级部门 ID</label><input v-model="deptForm.parentId" class="form-input" type="number" min="1" placeholder="根部门留空；填写已存在部门 ID" /><label class="form-label">排序</label><input v-model.number="deptForm.sortNo" class="form-input" type="number" min="0" placeholder="数字越小越靠前" /></template><template v-else><label class="form-label">字典类型</label><input v-model="dictForm.dictType" class="form-input" required placeholder="例如：status" /><label class="form-label">显示标签</label><input v-model="dictForm.dictLabel" class="form-input" required placeholder="例如：正常" /><label class="form-label">字典值</label><input v-model="dictForm.dictValue" class="form-input" required placeholder="例如：1" /><label class="form-label">排序</label><input v-model.number="dictForm.sortNo" class="form-input" type="number" min="0" placeholder="数字越小越靠前" /></template><div class="dialog-actions"><button class="secondary-button" type="button" @click="dialogVisible = false">取消</button><button class="primary-button compact-button" type="submit">保存</button></div></form></el-dialog>
</template>

<style scoped>
.tab-bar { display: flex; gap: 10px; margin-bottom: 16px; }.tab-bar .active { color: #fff; background: #244f3f; }.section-toolbar { display: flex; justify-content: space-between; align-items: center; gap: 14px; padding: 18px 20px; border-bottom: 1px solid #e7eee8; }.section-toolbar strong { display: block; color: #244a3c; font-size: 14px; }.section-toolbar span { display: block; margin-top: 4px; color: #87988f; font-size: 12px; }.compact-button { width: auto; padding: 0 18px; }.toolbar { display: flex; gap: 10px; margin: 14px 20px; }.toolbar .form-input { max-width: 260px; }.dict-help { margin: 14px 20px -2px; padding: 11px 13px; border-left: 3px solid #9abe63; border-radius: 5px; background: #f1f6e7; color: #687d5f; font-size: 12px; line-height: 1.7; }.permission-dialog { max-height: 52vh; overflow: auto; padding: 4px 2px; }.menu-option { display: grid; grid-template-columns: 18px minmax(120px, .8fr) minmax(180px, 1.2fr); align-items: center; gap: 8px; min-height: 44px; padding: 8px 10px; border-bottom: 1px solid #edf2ed; color: #315747; }.menu-option small { color: #8a9b91; overflow-wrap: anywhere; }.dialog-tip { margin: -4px 0 16px; color: #789087; font-size: 13px; line-height: 1.7; }.dialog-form { display: grid; gap: 2px; }.dialog-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 20px; }.secondary-button { width: auto; height: 42px; padding: 0 18px; border: 1px solid #cbd9ce; border-radius: 9px; background: #f7faf7; color: #335f4d; cursor: pointer; }@media (max-width: 800px) { .section-toolbar { align-items: flex-start; flex-direction: column; }.menu-option { grid-template-columns: 18px minmax(0, 1fr); }.menu-option small { grid-column: 2; } }
</style>
